import * as THREE from 'three/webgpu';
import {
  MeshBasicNodeMaterial,
  texture,
  uv,
  uvTransform
} from 'three/tsl';
import { gsap } from 'gsap';
import { primitives } from '@/primitives';
import { text } from '@/text';

export default function createNode(config, ctx) {
  // --- Root object ---------------------------------------------------------
  const root = new THREE.Object3D();

  // Position / Rotation / Scale from config (defaults if missing)
  const pos = config.position ?? [0, 0, 0];
  const rot = config.rotation ?? [0, 0, 0];
  const scl = config.scale ?? [1, 1, 1];

  root.position.set(pos[0], pos[1], pos[2]);
  root.rotation.set(rot[0], rot[1], rot[2]);
  root.scale.set(scl[0], scl[1], scl[2]);

  // --- Texture -------------------------------------------------------------
  const tex = ctx.textureLoader.load(config.assets?.imageUrl);
  // Assume texture is already loaded synchronously (cached)

  // --- Atlas UV region ------------------------------------------------------
  const atlasInfo = config.atlasRegion ?? {};
  const srcRect = atlasInfo.sourceRect ?? [0, 0, 512, 320];
  const [sx, sy, sw, sh] = srcRect;

  // Fallback to texture dimensions if atlas size not explicit
  const atlasWidth = atlasInfo.atlasWidth ?? (tex.image?.width ?? sw);
  const atlasHeight = atlasInfo.atlasHeight ?? (tex.image?.height ?? sh);

  const repeatU = sw / atlasWidth;
  const repeatV = sh / atlasHeight;
  const offsetU = sx / atlasWidth;
  const offsetV = sy / atlasHeight;

  // UV transform node to select the sub‑region
  const uvNode = uv();
  const uvRegion = uvTransform(uvNode, offsetU, offsetV, repeatU, repeatV);

  // Texture sampling node with transformed UVs
  const texNode = texture(tex, uvRegion);

  // --- Material -------------------------------------------------------------
  const material = new MeshBasicNodeMaterial({ map: texNode, transparent: true });

  // --- Geometry -------------------------------------------------------------
  const aspect = sw / sh;
  const geometry = new THREE.PlaneGeometry(aspect, 1);

  // --- Mesh (billboard) -----------------------------------------------------
  const mesh = new THREE.Mesh(geometry, material);
  mesh.onBeforeRender = (renderer, scene, camera) => {
    // Keep the plane facing the camera
    mesh.quaternion.copy(camera.quaternion);
  };
  root.add(mesh);

  // --- Cinematic primitives -------------------------------------------------
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const primitive of config.cinematicPrimitives) {
      const fn = ctx.primitives[primitive.name];
      if (typeof fn === 'function') {
        fn(root, primitive.params);
      }
    }
  }

  // --- User data ------------------------------------------------------------
  root.userData.handlers = {};

  root.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    tex.dispose();
    // Kill any GSAP timelines that might have been created (none here)
    gsap.globalTimeline.clear(true);
  };

  return root;
}
